export const SITE_BY_ID = Object.fromEntries(SITES.map((s) => [s.id, s]));

/**
 * The makePlot spec for a site, with the entrance the player chose.
 * A site with a corner (entranceSide has two sides) takes either; anything else takes
 * its roadSide. `side` is ignored when it is not one of the site's own entrances —
 * the plot's gate cannot stand on a side with no road.
 * @param {string} id
 * @param {'N'|'E'|'S'|'W'|null} [side]
 */
export function siteSpec(id, side = null) {
  const s = SITE_BY_ID[id];
  if (!s) return null;
  const gateSide = side && s.entranceSide.includes(side) ? side : s.roadSide;
  return {
    id: s.id,
    ha: s.ha,
    w: s.tiles[0],
    h: s.tiles[1],
    water: s.water,
    forest: s.forest,
    slope: s.slopePct,
    kmFromShop: s.kmFromShop,
    // the DEM anchor: a site is not one of the baked plot anchors, it is a map pixel
    anchor: { x: s.x, y: s.y },
    gateSide,
    roadSide: s.roadSide,
    entranceSide: s.entranceSide.slice(),
    gateBearing: s.gateBearing,
    site: s.id,
    // the baked price and the land-mortgage terms (plotmap.LAND_MORTGAGE)
    price: s.price,
    landMortgage: true,
    // old cropland carries the wattle; the rough ground carries more of it
    alienFrac: s.alienFrac,
  };
}

/** The sites with a corner: two roads, two edges, the player picks. */
export const CORNER_SITES = SITES.filter((s) => s.entranceSide.length > 1);

/** The cheap ground: steep, remote, dry — the tier a poor life can actually buy. */
export const ROUGH_SITES = SITES.filter((s) => s.tier === 'rough');

/** The workable ground: the 24 plots that need a mortgage or a full purse. */
export const GOOD_SITES = SITES.filter((s) => s.tier === 'good');

