/**
 * The makePlot spec for a site played as a given LIFE. The ground comes from the
 * catalog; the terms come from the life — the incomer's H$320k already promised to a
 * builder, the stayed's H$40k. Those are properties of who you are, not of the land,
 * and dropping them would hand the incomer a free H$320,000.
 * @param {string} id
 * @param {'N'|'E'|'S'|'W'|null} [side]
 * @param {{plot:{committed?:number, cash?:number}}} option a START_OPTIONS entry
 */
export function lifeSpec(id, side, option) {
  const spec = siteSpec(id, side);
  if (!spec) return null;
  const terms = (option && option.plot) || {};
  return { ...spec, committed: terms.committed, cash: terms.cash };
}
